async () => {
  const start = Date.now();
  const timeout = 90000;
  while (Date.now() - start < timeout) {
    const btns = Array.from(document.querySelectorAll('button'));
    const renderBtn = btns.find(b => b.textContent && b.textContent.includes('正在渲染高清图表并生成 PDF'));
    const doneBtn = btns.find(b => b.textContent && b.textContent.includes('立即编译导出高清 PDF') && !b.disabled);
    const toasts = Array.from(document.querySelectorAll('*')).filter(el => el.children.length === 0 && el.textContent && (el.textContent.includes('PDF') && (el.textContent.includes('成功') || el.textContent.includes('完成') || el.textContent.includes('失败') || el.textContent.includes('错误')))).map(el => el.textContent.trim()).slice(0, 5);
    if (!renderBtn) {
      return { status: 'render_finished', elapsed: Date.now() - start, doneBtnExists: !!doneBtn, toasts };
    }
    await new Promise(r => setTimeout(r, 2000));
  }
  return { status: 'timeout', elapsed: Date.now() - start };
}

() => {
  const btns = Array.from(document.querySelectorAll('button'));
