      rect: { x: Math.round(rect.x), y: Math.round(rect.y), w: Math.round(rect.width), h: Math.round(rect.height) },
      parentClass: b.parentElement ? b.parentElement.className.toString().slice(0, 80) : null
    };
  });
}

() => {
  window.__pdfErrors = [];
  window.__origConsoleError = console.error;
  console.error = function(...args) {
    window.__pdfErrors.push(args.map(a => {
      try {
        if (a instanceof Error) return { name: a.name, message: a.message, stack: a.stack ? a.stack.slice(0, 500) : null };
        return typeof a === 'object' ? JSON.stringify(a).slice(0, 300) : String(a);
      } catch (e) { return 'unserializable'; }
    }));
    return window.__origConsoleError.apply(console, args);
  };
  window.addEventListener('unhandledrejection', (e) => {
    window.__pdfErrors.push(['unhandledrejection', e.reason ? (e.reason.message || String(e.reason)) : 'unknown', e.reason && e.reason.stack ? e.reason.stack.slice(0, 500) : null]);
  });
  window.addEventListener('error', (e) => {
    window.__pdfErrors.push(['windowerror', e.message, e.filename, e.lineno]);
  });
  return 'error capture installed';
}

() => {
