() => {
  window.__downloads = [];
  // Intercept anchor clicks with download attribute
  const origClick = HTMLAnchorElement.prototype.click;
  HTMLAnchorElement.prototype.click = function() {
    if (this.download || (this.href && this.href.startsWith('blob:'))) {
      window.__downloads.push({ href: (this.href || '').slice(0, 80), download: this.download || null, time: Date.now() });
    }
    return origClick.apply(this, arguments);
  };
  const origCreate = URL.createObjectURL;
  URL.createObjectURL = function(blob) {
    const url = origCreate.apply(this, arguments);
    window.__downloads.push({ createdBlob: true, type: blob && blob.type, size: blob && blob.size, url: url.slice(0, 60), time: Date.now() });
    return url;
  };
  return 'download interceptor installed';
}

() => {
