async () => {
  // Verify the captured blob is a valid PPTX by checking its content signature
  const dl = (window.__downloads || []).find(d => d.href);
  if (!dl) return { blobCheck: 'no download captured' };
  try {
    const resp = await fetch(dl.href);
    const buf = await resp.arrayBuffer();
    const bytes = new Uint8Array(buf.slice(0, 4));
    const signature = Array.from(bytes).map(b => b.toString(16).padStart(2, '0')).join(' ');
    return {
      blobCheck: 'fetched',
      size: buf.byteLength,
      signatureHex: signature,
      isZipPkSignature: bytes[0] === 0x50 && bytes[1] === 0x4B,
      filename: dl.download
    };
  } catch (e) {
    return { blobCheck: 'fetch failed', error: String(e) };
  }
}

() => {
  window.__downloads = [];
  return 'cleared, ready for real click test';
}

async () => {
