() => {
  const btns = Array.from(document.querySelectorAll('button'));
  const realBtn = btns.find(b => {
    const r = b.getBoundingClientRect();
    return b.textContent && b.textContent.includes('下载 PPT 简报') && r.y > 400 && r.width > 0;
  });
  if (!realBtn) return 'real button not found';
  const r = realBtn.getBoundingClientRect();
  const cx = r.x + r.width / 2, cy = r.y + r.height / 2;
  const topEl = document.elementFromPoint(cx, cy);
  // Also check what overlay containers exist
  const overlays = Array.from(document.querySelectorAll('div')).filter(d => {
    const s = window.getComputedStyle(d);
    const dr = d.getBoundingClientRect();
    return (s.position === 'fixed' || s.position === 'absolute') && dr.width >= window.innerWidth * 0.9 && dr.height >= window.innerHeight * 0.9;
  }).map(d => ({
    className: d.className.toString().slice(0, 100),
    position: window.getComputedStyle(d).position,
    zIndex: window.getComputedStyle(d).zIndex,
    pointerEvents: window.getComputedStyle(d).pointerEvents,
    display: window.getComputedStyle(d).display,
    visibility: window.getComputedStyle(d).visibility,
    left: Math.round(d.getBoundingClientRect().left),
    top: Math.round(d.getBoundingClientRect().top)
  }));
  return {
    btnCenter: { x: Math.round(cx), y: Math.round(cy) },
    topElementTag: topEl ? topEl.tagName : null,
    topElementText: topEl ? (topEl.textContent || '').slice(0, 50) : null,
    topElementIsBtn: topEl === realBtn,
    topElementContainedInBtn: topEl ? realBtn.contains(topEl) : null,
    overlays
  };
}

() => {
  const overlays = document.querySelectorAll('.html2pdf__overlay');
  const count = overlays.length;
  overlays.forEach(o => o.remove());
  // verify the real PPT button is now clickable
  const btns = Array.from(document.querySelectorAll('button'));
  const realBtn = btns.find(b => {
    const r = b.getBoundingClientRect();
    return b.textContent && b.textContent.includes('下载 PPT 简报') && r.y > 400 && r.width > 0;
  });
  let topCheck = null;
  if (realBtn) {
    const r = realBtn.getBoundingClientRect();
    const topEl = document.elementFromPoint(r.x + r.width / 2, r.y + r.height / 2);
    topCheck = { isBtnOrChild: topEl === realBtn || realBtn.contains(topEl), topTag: topEl && topEl.tagName };
  }
  window.__downloads = [];
  return { removedOverlays: count, topCheck };
}

