() => {
  // Prevent blob revocation so we can verify content
  window.__blobs = [];
  URL.revokeObjectURL = function(url) { /* no-op for verification */ };
  const origCreate = URL.createObjectURL;
  // already patched; ensure blobs recorded
  window.__downloads = [];
  return 'revoke blocked';
}

async () => {
  await new Promise(r => setTimeout(r, 5000));
  const dls = window.__downloads || [];
  const dl = dls.find(d => d.href);
  if (!dl) return { status: 'no download captured', dls };
  try {
    const resp = await fetch(dl.href);
    const buf = await resp.arrayBuffer();
    const bytes = new Uint8Array(buf);
    const sig = Array.from(bytes.slice(0, 4)).map(b => b.toString(16).padStart(2, '0')).join(' ');
    // check for pptx content types entry
    const text = new TextDecoder('utf-8', { fatal: false }).decode(bytes.slice(0, 2000));
    return {
      status: 'verified',
      size: buf.byteLength,
      signatureHex: sig,
      isZipPk: bytes[0] === 0x50 && bytes[1] === 0x4B,
      filename: dl.download,
      mimeType: dls[0] && dls[0].type,
      headSnippet: text.slice(0, 120)
    };
  } catch (e) {
    return { status: 'fetch failed', error: String(e), filename: dl.download };
  }
}
